'use strict';
// Shared helpers for the angular-jira-clone ingest drivers.
// No credentials, no host-absolute paths: every path is resolved from the repository root.

const fs = require('fs');
const path = require('path');
const https = require('https');
const crypto = require('crypto');

const SLUG = 'angular-jira-clone';
const UNIT = 'lrapr-t005/a2-ingest-jira-clone';
const CONSENT_ID = 'VL-LEGACY-CORPUS-2026-08-10';
const REPO = 'trungvose/jira-clone-angular';
const COMMIT = '059455b9933a236456524925065bce2c295e2d9a';

const ROOT = path.resolve(__dirname, '..', '..', '..', '..');
const EVIDENCE = path.join(ROOT, 'evidence', 'ingests', SLUG);
const LEDGER = path.join(EVIDENCE, 'probe-ledger.ndjson');
const TRANSCRIPT = path.join(EVIDENCE, 'transcript.ndjson');
const CACHE = path.join(ROOT, '.versionless', 'cache');

function requireConsent() {
  if (process.env.VERSIONLESS_NETWORK_MODE !== 'consented') {
    throw new Error('refusing to touch the network: VERSIONLESS_NETWORK_MODE is not "consented"');
  }
  if (process.env.VERSIONLESS_CONSENT_ID !== CONSENT_ID) {
    throw new Error('refusing to touch the network: VERSIONLESS_CONSENT_ID does not match the purpose-bound consent id');
  }
}

function sha256(buf) {
  return crypto.createHash('sha256').update(buf).digest('hex');
}

function gitBlobSha(buf) {
  const header = Buffer.from(`blob ${buf.length}\0`, 'utf8');
  return crypto.createHash('sha1').update(Buffer.concat([header, buf])).digest('hex');
}

function appendNdjson(file, obj) {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.appendFileSync(file, JSON.stringify(obj) + '\n');
}

function ledger(entry) {
  appendNdjson(LEDGER, Object.assign({ at: new Date().toISOString() }, entry));
}

function transcript(entry) {
  appendNdjson(TRANSCRIPT, Object.assign({ at: new Date().toISOString() }, entry));
}

// Plain GET. Redirects are never followed unless maxRedirects is raised explicitly
// (only the labeled LFS deviation may do that, and it ledgers each hop).
function get(url, opts = {}) {
  const maxRedirects = opts.maxRedirects || 0;
  return new Promise((resolve, reject) => {
    const run = (target, hops) => {
      const req = https.get(
        target,
        {
          headers: Object.assign(
            {
              'user-agent': 'versionless-legacy-corpus-ingest',
              accept: opts.accept || 'application/vnd.github+json',
              'accept-encoding': 'identity',
            },
            opts.headers || {}
          ),
        },
        (res) => {
          const chunks = [];
          res.on('data', (c) => chunks.push(c));
          res.on('end', () => {
            const body = Buffer.concat(chunks);
            const loc = res.headers.location;
            if (loc && res.statusCode >= 300 && res.statusCode < 400 && hops < maxRedirects) {
