'use strict';
// Step 1+2: probe repository and pinned commit identity, pull the recursive git tree,
// and fetch the source archive twice, requiring the two streams to be byte-identical.

const fs = require('fs');
const path = require('path');
const L = require('./lib.cjs');

async function main() {
  L.requireConsent();
  L.transcript({
    step: 'probe-identity-and-double-fetch-archive',
    runner: 'node evidence/ingests/angular-jira-clone/scripts/acquire-source.cjs',
    consentId: L.CONSENT_ID,
    networkMode: 'consented',
    wrote: [
      'evidence/ingests/angular-jira-clone/probe-ledger.ndjson',
      'evidence/ingests/angular-jira-clone/probe-tree.json',
      'evidence/ingests/angular-jira-clone/identity.json',
      '.versionless/cache/angular-jira-clone-source/archive',
    ],
  });

  const repoRes = await L.ledgeredGet('admission-gate-probe', `https://api.github.com/repos/${L.REPO}`);
  const repo = JSON.parse(repoRes.body.toString('utf8'));

  const commitRes = await L.ledgeredGet(
    'admission-gate-probe',
    `https://api.github.com/repos/${L.REPO}/commits/${L.COMMIT}`
  );
  const commit = JSON.parse(commitRes.body.toString('utf8'));
  if (commit.sha !== L.COMMIT) throw new Error(`wire sha ${commit.sha} does not equal the pinned sha`);

  const treeSha = commit.commit.tree.sha;
  const treeRes = await L.ledgeredGet(
    'admission-gate-probe',
    `https://api.github.com/repos/${L.REPO}/git/trees/${treeSha}?recursive=1`
  );
  const tree = JSON.parse(treeRes.body.toString('utf8'));
  fs.mkdirSync(L.EVIDENCE, { recursive: true });
  fs.writeFileSync(path.join(L.EVIDENCE, 'probe-tree.json'), treeRes.body);

  const archiveUrl = `https://codeload.github.com/${L.REPO}/tar.gz/${L.COMMIT}`;
  const archiveDir = path.join(L.CACHE, 'angular-jira-clone-source', 'archive');
  fs.mkdirSync(archiveDir, { recursive: true });
  const streams = [];
  for (const n of [1, 2]) {
    const r = await L.ledgeredGet('source-archive-fetch', archiveUrl, { accept: 'application/x-gzip' });
    fs.writeFileSync(path.join(archiveDir, `archive-${n}.tar.gz`), r.body);
    streams.push({ stream: n, status: r.status, bytes: r.bytes, sha256: r.sha256, setCookie: r.setCookie });
  }
  const identical = streams[0].sha256 === streams[1].sha256 && streams[0].bytes === streams[1].bytes;

  const blobs = tree.tree.filter((e) => e.type === 'blob');
  const dirs = tree.tree.filter((e) => e.type === 'tree');
  const symlinks = blobs.filter((e) => e.mode === '120000');
  const gitlinks = tree.tree.filter((e) => e.type === 'commit' || e.mode === '160000');
  const execBlobs = blobs.filter((e) => e.mode === '100755');

  L.writeJson(path.join(L.EVIDENCE, 'identity.json'), {
    schemaVersion: 'versionless.legacy-corpus-identity.v1',
    slug: L.SLUG,
    unit: L.UNIT,
    consentId: L.CONSENT_ID,
    repository: {
      id: repo.id,
      fullName: repo.full_name,
      private: repo.private,
      archived: repo.archived,
      disabled: repo.disabled,
      fork: repo.fork,
      defaultBranch: repo.default_branch,
      createdAt: repo.created_at,
      pushedAt: repo.pushed_at,
      license: repo.license ? { key: repo.license.key, spdx: repo.license.spdx_id, name: repo.license.name } : null,
      homepage: repo.homepage,
      description: repo.description,
      stargazers: repo.stargazers_count,
      responseBytes: repoRes.bytes,
      responseSha256: repoRes.sha256,
    },
    revision: {
      commitSha: commit.sha,
      committerDate: commit.commit.committer.date,
      authorDate: commit.commit.author.date,
      commitSubject: commit.commit.message.split('\n')[0],
      verification: commit.commit.verification,
      rootTreeSha: treeSha,
      parents: commit.parents.map((p) => p.sha),
    },
    tree: {
      entries: tree.tree.length,
      blobs: blobs.length,
      directories: dirs.length,
      symlinks: symlinks.length,
      gitlinks: gitlinks.length,
      executableBlobs: execBlobs.length,
      truncated: tree.truncated,
      blobBytes: blobs.reduce((a, e) => a + (e.size || 0), 0),
    },
    archive: {
      url: archiveUrl,
      streams,
      byteIdentical: identical,
    },
  });

  console.log(
    JSON.stringify(
      {
        commit: commit.sha,
        date: commit.commit.committer.date,
        treeSha,
        blobs: blobs.length,
        truncated: tree.truncated,
        archiveIdentical: identical,
        archiveSha256: streams[0].sha256,
        archiveBytes: streams[0].bytes,
        githubLicense: repo.license && repo.license.spdx_id,
      },
      null,
      2
    )
  );
}

main().catch((e) => {
  console.error('FAILED:', e.message);
  process.exit(1);
});

