      blobs: blobs.length,
      directories: dirs.length,
      symlinks: symlinks.length,
      gitlinks: gitlinks.length,
      executableBlobs: execBlobs.length,
      truncated: tree.truncated,
      blobBytes: blobs.reduce((a, e) => a + (e.size || 0), 0),
    },
    archive: {
      url: archiveUrl,
      streams,
      byteIdentical: identical,
    },
  });

  console.log(
