'use strict';
// Step 3 (offline): extract archive stream 1 and prove every regular file hashes,
// as a git blob object, to exactly the sha the recursive tree records for that path.
// Also inventories Git LFS pointer stubs, because a codeload archive reproduces pointers, not payloads.

const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');
const L = require('./lib.cjs');

const CACHE_ROOT = path.join(L.CACHE, 'angular-jira-clone-source');
const EXTRACT = path.join(CACHE_ROOT, 'verify', 'extracted');

function walk(dir, base, out) {
  for (const name of fs.readdirSync(dir)) {
    const full = path.join(dir, name);
    const st = fs.lstatSync(full);
    const rel = path.posix.join(base, name);
    if (st.isDirectory()) walk(full, rel, out);
    else out.push({ rel, full, symlink: st.isSymbolicLink(), mode: st.mode });
  }
  return out;
}

function main() {
  L.transcript({
    step: 'reconcile-archive-against-git-tree',
    runner: 'node evidence/ingests/angular-jira-clone/scripts/reconcile.cjs',
    network: 'none',
    wrote: ['evidence/ingests/angular-jira-clone/reconciliation.json', 'evidence/ingests/angular-jira-clone/lfs.json'],
  });

  const tree = JSON.parse(fs.readFileSync(path.join(L.EVIDENCE, 'probe-tree.json'), 'utf8'));
  const archive = path.join(CACHE_ROOT, 'archive', 'archive-1.tar.gz');

  const listing = execFileSync('tar', ['-tzf', archive], { maxBuffer: 1 << 28 }).toString('utf8').split('\n').filter(Boolean);
  const roots = new Set(listing.map((l) => l.split('/')[0]));
  const dirEntries = listing.filter((l) => l.endsWith('/'));
  const fileEntries = listing.filter((l) => !l.endsWith('/'));
  const traversal = listing.filter((l) => l.split('/').includes('..'));
  const absolute = listing.filter((l) => l.startsWith('/'));

  fs.rmSync(EXTRACT, { recursive: true, force: true });
  fs.mkdirSync(EXTRACT, { recursive: true });
  execFileSync('tar', ['-xzf', archive, '-C', EXTRACT]);

  const single = [...roots][0];
  const appRoot = path.join(EXTRACT, single);
  const files = walk(appRoot, '', []);

  const byPath = new Map();
  for (const e of tree.tree) if (e.type === 'blob') byPath.set(e.path, e);

  const missing = [];
  const extra = [];
  const mismatched = [];
  const manifest = [];
  const lfsPointers = [];

  for (const f of files) {
    const entry = byPath.get(f.rel);
    const buf = fs.readFileSync(f.full);
    const blob = L.gitBlobSha(buf);
    if (!entry) {
      extra.push(f.rel);
      continue;
    }
    if (entry.sha !== blob) mismatched.push({ path: f.rel, treeSha: entry.sha, archiveSha: blob });
    manifest.push(`${f.rel} ${blob} ${buf.length}`);
    if (buf.length < 400 && buf.slice(0, 40).toString('utf8').startsWith('version https://git-lfs')) {
      const text = buf.toString('utf8');
      const oid = /oid sha256:([0-9a-f]{64})/.exec(text);
      const size = /size (\d+)/.exec(text);
      lfsPointers.push({ path: f.rel, oid: oid && oid[1], payloadBytes: size && Number(size[1]), pointerBytes: buf.length });
    }
  }
  const seen = new Set(files.map((f) => f.rel));
  for (const p of byPath.keys()) if (!seen.has(p)) missing.push(p);

  manifest.sort();
  const normalized = L.sha256(Buffer.from(manifest.join('\n') + '\n', 'utf8'));

  const gitattributesPath = path.join(appRoot, '.gitattributes');
  const gitattributes = fs.existsSync(gitattributesPath) ? fs.readFileSync(gitattributesPath, 'utf8') : null;

  L.writeJson(path.join(L.EVIDENCE, 'reconciliation.json'), {
    schemaVersion: 'versionless.legacy-corpus-reconciliation.v1',
    slug: L.SLUG,
    method:
      'Every regular file in the extracted archive was hashed as a git blob object and compared byte-for-byte against the sha recorded for the same path in the recursive git tree at the pinned revision.',
    singleRoot: single,
    rootCount: roots.size,
    archiveEntries: listing.length,
    directories: dirEntries.length,
    regularFiles: fileEntries.length,
    specialEntries: files.filter((f) => f.symlink).length,
    pathTraversalEntries: traversal.length,
    absolutePathEntries: absolute.length,
    gitBlobs: byPath.size,
    extractedFiles: files.length,
    missingFiles: missing.length,
    extraFiles: extra.length,
    mismatchedBlobs: mismatched.length,
    missing,
    extra,
    mismatched,
    normalizedManifestSha256: normalized,
    archiveMatchesGitTree: missing.length === 0 && extra.length === 0 && mismatched.length === 0,
  });

  L.writeJson(path.join(L.EVIDENCE, 'lfs.json'), {
    schemaVersion: 'versionless.legacy-corpus-lfs.v1',
    slug: L.SLUG,
    unit: L.UNIT,
    checkedBeforeTrustingAssets: true,
    checkPrompt:
      'The sibling factoriolab ingest (lrapr-t005/a1) found LFS pointer stubs in its archive, which broke its unmodified baseline build. This unit therefore reads .gitattributes at the pinned revision and scans every extracted blob for a pointer header before assuming any asset ships in-tree.',
    gitattributesPresent: gitattributes !== null,
    gitattributesText: gitattributes,
    lfsFilterRoutes: gitattributes ? gitattributes.split('\n').filter((l) => l.includes('filter=lfs')) : [],
    pointerFilesFound: lfsPointers.length,
    pointers: lfsPointers,
    payloadsRequired: lfsPointers.length > 0,
    materialisation: lfsPointers.length > 0 ? 'pending — see baseline-attempt.json' : 'not applicable: no Git LFS pointer stub exists in the archive, so the pinned tree carries its assets in full',
  });

  console.log(
    JSON.stringify(
      {
        root: single,
        entries: listing.length,
        files: files.length,
        blobs: byPath.size,
        missing: missing.length,
        extra: extra.length,
        mismatched: mismatched.length,
        normalized,
        gitattributes: gitattributes,
        lfsPointerFiles: lfsPointers.length,
      },
      null,
      2
    )
  );
}

main();

