'use strict';
// Step 4+5: acquire the declared legacy Node runtime (.nvmrc = 16 -> Node 16.20.2, native arm64),
// verify its digest against the release SHASUMS256.txt, then run one truthful
// `npm ci` and one production build of the reconciled source. Outcomes are recorded as they happen.

const fs = require('fs');
const path = require('path');
const { execFileSync, spawnSync } = require('child_process');
const L = require('./lib.cjs');

const NODE_VERSION = '16.20.2';
const NODE_ARCH = 'darwin-arm64';
const NODE_TARBALL = `node-v${NODE_VERSION}-${NODE_ARCH}.tar.gz`;
const NODE_URL = `https://nodejs.org/dist/v${NODE_VERSION}/${NODE_TARBALL}`;
const SHASUMS_URL = `https://nodejs.org/dist/v${NODE_VERSION}/SHASUMS256.txt`;

const RUNTIME_CACHE = path.join(L.CACHE, 'angular-jira-clone-runtime');
const BASELINE = path.join(L.CACHE, 'angular-jira-clone-baseline');
const APP = path.join(BASELINE, 'app');
const SRC = path.join(
  L.CACHE,
  'angular-jira-clone-source',
  'verify',
  'extracted',
  `jira-clone-angular-${L.COMMIT}`
);

async function acquireRuntime() {
  fs.mkdirSync(RUNTIME_CACHE, { recursive: true });
  const nodeHome = path.join(RUNTIME_CACHE, `node-v${NODE_VERSION}-${NODE_ARCH}`);
  const tarball = path.join(RUNTIME_CACHE, NODE_TARBALL);

  const shasums = await L.ledgeredGet('legacy-runtime-acquire', SHASUMS_URL, { accept: 'text/plain', maxRedirects: 3 });
  const expected = shasums.body
    .toString('utf8')
    .split('\n')
    .map((l) => l.trim().split(/\s+/))
    .find((p) => p[1] === NODE_TARBALL);
  if (!expected) throw new Error('the release SHASUMS256.txt does not list the requested tarball');

  const rt = await L.ledgeredGet('legacy-runtime-acquire', NODE_URL, { accept: 'application/gzip', maxRedirects: 3 });
  if (rt.sha256 !== expected[0]) {
    throw new Error(`runtime digest mismatch: got ${rt.sha256}, SHASUMS256.txt says ${expected[0]}`);
  }
  fs.writeFileSync(tarball, rt.body);
  fs.rmSync(nodeHome, { recursive: true, force: true });
  execFileSync('tar', ['-xzf', tarball, '-C', RUNTIME_CACHE]);

  const bin = path.join(nodeHome, 'bin');
  const reported = execFileSync(path.join(bin, 'node'), ['-v']).toString().trim();
  const npmReported = execFileSync(path.join(bin, 'npm'), ['-v'], {
    env: Object.assign({}, process.env, { PATH: `${bin}:${process.env.PATH}` }),
  })
    .toString()
    .trim();

  return {
    nodeHome,
    bin,
    record: {
      version: NODE_VERSION,
      platform: NODE_ARCH,
      url: NODE_URL,
      shasumsUrl: SHASUMS_URL,
      sha256: rt.sha256,
      bytes: rt.bytes,
      digestVerifiedAgainstOfficialShasums: true,
      shasumsSha256: shasums.sha256,
      reportedNodeVersion: reported,
      bundledNpmVersion: npmReported,
      translationLayer: 'none — this is a native arm64 build running on darwin-arm64',
    },
  };
}

function run(cmd, args, opts) {
  const started = Date.now();
  const r = spawnSync(cmd, args, opts);
  return {
    command: `${path.basename(cmd)} ${args.join(' ')}`,
    exitStatus: r.status,
    durationMs: Date.now() - started,
    stdout: (r.stdout || Buffer.alloc(0)).toString('utf8'),
    stderr: (r.stderr || Buffer.alloc(0)).toString('utf8'),
  };
}

function dirStats(dir) {
  if (!fs.existsSync(dir)) return { files: 0, bytes: 0 };
  let files = 0;
  let bytes = 0;
  const stack = [dir];
  while (stack.length) {
    const d = stack.pop();
    for (const name of fs.readdirSync(d)) {
      const full = path.join(d, name);
      const st = fs.lstatSync(full);
      if (st.isDirectory()) stack.push(full);
      else {
        files += 1;
        bytes += st.size;
      }
    }
  }
  return { files, bytes };
}

async function main() {
  L.requireConsent();
  L.transcript({
    step: 'baseline-install-and-production-build',
    runner: 'node evidence/ingests/angular-jira-clone/scripts/baseline.cjs',
    consentId: L.CONSENT_ID,
    networkMode: 'consented',
    wrote: [
      'evidence/ingests/angular-jira-clone/probe-ledger.ndjson',
      'evidence/ingests/angular-jira-clone/baseline-result.json',
      '.versionless/cache/angular-jira-clone-runtime',
      '.versionless/cache/angular-jira-clone-baseline',
    ],
  });

  const runtime = await acquireRuntime();

  fs.rmSync(APP, { recursive: true, force: true });
  fs.mkdirSync(BASELINE, { recursive: true });
  fs.cpSync(SRC, APP, { recursive: true });

  const home = path.join(BASELINE, 'home');
  fs.mkdirSync(home, { recursive: true });
  const env = Object.assign({}, process.env, {
    PATH: `${runtime.bin}:${process.env.PATH}`,
    HOME: home,
    npm_config_cache: path.join(BASELINE, 'npm-cache'),
    NG_CLI_ANALYTICS: 'false',
    CI: 'true',
  });

  const install = run(path.join(runtime.bin, 'npm'), ['ci', '--no-audit', '--no-fund'], {
    cwd: APP,
    env,
    maxBuffer: 1 << 28,
  });
  fs.writeFileSync(path.join(BASELINE, 'install.stdout.log'), install.stdout);
  fs.writeFileSync(path.join(BASELINE, 'install.stderr.log'), install.stderr);

  let build = null;
  if (install.exitStatus === 0) {
    build = run(path.join(runtime.bin, 'npx'), ['ng', 'build', '--configuration', 'production'], {
      cwd: APP,
      env,
      maxBuffer: 1 << 28,
    });
    fs.writeFileSync(path.join(BASELINE, 'build.stdout.log'), build.stdout);
    fs.writeFileSync(path.join(BASELINE, 'build.stderr.log'), build.stderr);
  }

  const dist = dirStats(path.join(APP, 'dist'));

  L.writeJson(path.join(L.EVIDENCE, 'baseline-result.json'), {
    runtime: runtime.record,
    install: {
      command: install.command,
      exitStatus: install.exitStatus,
      durationMs: install.durationMs,
      stdoutTail: install.stdout.split('\n').slice(-25).join('\n'),
      stderrTail: install.stderr.split('\n').slice(-60).join('\n'),
    },
    build: build && {
      command: build.command,
      exitStatus: build.exitStatus,
      durationMs: build.durationMs,
      stdoutTail: build.stdout.split('\n').slice(-60).join('\n'),
      stderrTail: build.stderr.split('\n').slice(-60).join('\n'),
    },
    dist,
  });

  console.log(
    JSON.stringify(
      {
        node: runtime.record.reportedNodeVersion,
        npm: runtime.record.bundledNpmVersion,
        installExit: install.exitStatus,
        installMs: install.durationMs,
        buildExit: build && build.exitStatus,
        buildMs: build && build.durationMs,
        dist,
      },
      null,
      2
    )
  );
}

main().catch((e) => {
  console.error('FAILED:', e.message);
  process.exit(1);
});

