'use strict';
// Offline: key-file digests, lockfile closure statistics, and tree shape facts
// used by license.json, closure.json and admission.json.

const fs = require('fs');
const path = require('path');
const L = require('./lib.cjs');

const SRC = path.join(L.CACHE, 'angular-jira-clone-source', 'verify', 'extracted', `jira-clone-angular-${L.COMMIT}`);
const tree = JSON.parse(fs.readFileSync(path.join(L.EVIDENCE, 'probe-tree.json'), 'utf8'));
const treeByPath = new Map(tree.tree.filter((e) => e.type === 'blob').map((e) => [e.path, e]));

function digest(rel) {
  const buf = fs.readFileSync(path.join(SRC, rel));
  const t = treeByPath.get(rel);
  return { path: rel, bytes: buf.length, sha256: L.sha256(buf), gitBlobSha: L.gitBlobSha(buf), inTree: Boolean(t), treeSha: t && t.sha };
}

const keyFiles = ['LICENSE', 'package.json', 'package-lock.json', 'angular.json', '.nvmrc', 'webpack.config.js', 'tsconfig.json', 'tailwind.config.js'].map(digest);

const lock = JSON.parse(fs.readFileSync(path.join(SRC, 'package-lock.json'), 'utf8'));
const pkgs = lock.packages || {};
const entries = Object.entries(pkgs).filter(([k]) => k !== '');
const hosts = {};
let noIntegrity = 0;
let gitOrTarball = 0;
let dev = 0;
let prod = 0;
let link = 0;
for (const [name, meta] of entries) {
  if (meta.link) {
    link += 1;
    continue;
  }
  if (meta.resolved) {
    try {
      const h = new URL(meta.resolved).host;
      hosts[h] = (hosts[h] || 0) + 1;
      if (!/^https:\/\/registry\.npmjs\.org\//.test(meta.resolved)) gitOrTarball += 1;
    } catch (e) {
      gitOrTarball += 1;
    }
  } else {
    hosts['(no resolved field)'] = (hosts['(no resolved field)'] || 0) + 1;
  }
  if (!meta.integrity) noIntegrity += 1;
  if (meta.dev) dev += 1;
  else prod += 1;
  void name;
}

const pkg = JSON.parse(fs.readFileSync(path.join(SRC, 'package.json'), 'utf8'));
const license = fs.readFileSync(path.join(SRC, 'LICENSE'), 'utf8');

const licenceFilesInTree = [...treeByPath.keys()].filter((p) => /(^|\/)(LICENSE|LICENCE|COPYING|NOTICE)(\.|$)/i.test(p));

const out = {
  keyFiles,
  license: {
    firstLine: license.split('\n')[0],
    copyrightLine: license.split('\n').find((l) => /Copyright/i.test(l)),
    titleLinePresent: /^MIT License\s*$/m.test(license),
    permissionGrantPresent: license.includes('Permission is hereby granted, free of charge'),
    noticeRetentionClausePresent: license.includes('shall be included in all copies or substantial portions'),
    warrantyDisclaimerPresent: license.includes('WITHOUT WARRANTY OF ANY KIND'),
    lineCount: license.split('\n').length,
  },
  manifest: {
    name: pkg.name,
    version: pkg.version,
    private: pkg.private === true,
    licenseFieldPresent: Object.prototype.hasOwnProperty.call(pkg, 'license'),
    licenseField: pkg.license === undefined ? null : pkg.license,
    enginesPresent: Object.prototype.hasOwnProperty.call(pkg, 'engines'),
    directDependencies: Object.keys(pkg.dependencies || {}).length,
    directDevDependencies: Object.keys(pkg.devDependencies || {}).length,
    scripts: pkg.scripts,
  },
  lock: {
    lockfileVersion: lock.lockfileVersion,
    rootName: lock.name,
    rootVersion: lock.version,
    totalEntries: entries.length,
    linkEntries: link,
    devEntries: dev,
    productionEntries: prod,
    entriesWithoutIntegrity: noIntegrity,
    resolvedHosts: hosts,
    nonRegistryResolutions: gitOrTarball,
    hasLegacyDependenciesBlock: Boolean(lock.dependencies),
  },
  licenceFilesInTree,
  treeShape: {
    blobs: treeByPath.size,
    committedNodeModules: [...treeByPath.keys()].filter((p) => p.startsWith('node_modules/')).length,
    committedDist: [...treeByPath.keys()].filter((p) => p.startsWith('dist/')).length,
    specFiles: [...treeByPath.keys()].filter((p) => p.endsWith('.spec.ts')).length,
    typescriptFiles: [...treeByPath.keys()].filter((p) => p.endsWith('.ts')).length,
    htmlTemplates: [...treeByPath.keys()].filter((p) => p.endsWith('.html')).length,
    storyFiles: [...treeByPath.keys()].filter((p) => p.endsWith('.stories.ts')).length,
    largestBlobs: [...treeByPath.values()].sort((a, b) => b.size - a.size).slice(0, 8).map((e) => ({ path: e.path, size: e.size })),
  },
};

console.log(JSON.stringify(out, null, 2));

