// (a) the repository's own `npm run build` script, unmodified — a second observation, not a deviation;
// (b) one labeled deviation: delete the single invalid `extractCss` key from the production
//     configuration in angular.json (in the git-ignored baseline working tree only) and re-run the
//     production build, to establish whether that key is the whole of the failure.
// No network. No change to the acquired source archive or to the dependency closure.

const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');
const L = require('./lib.cjs');

const BASELINE = path.join(L.CACHE, 'angular-jira-clone-baseline');
const APP = path.join(BASELINE, 'app');
const BIN = path.join(L.CACHE, 'angular-jira-clone-runtime', 'node-v16.20.2-darwin-arm64', 'bin');

const env = Object.assign({}, process.env, {
  PATH: `${BIN}:${process.env.PATH}`,
  HOME: path.join(BASELINE, 'home'),
  npm_config_cache: path.join(BASELINE, 'npm-cache'),
  NG_CLI_ANALYTICS: 'false',
  CI: 'true',
});

function run(label, cmd, args) {
  const started = Date.now();
  const r = spawnSync(path.join(BIN, cmd), args, { cwd: APP, env, maxBuffer: 1 << 28 });
  const stdout = (r.stdout || Buffer.alloc(0)).toString('utf8');
  const stderr = (r.stderr || Buffer.alloc(0)).toString('utf8');
  fs.writeFileSync(path.join(BASELINE, `${label}.stdout.log`), stdout);
  fs.writeFileSync(path.join(BASELINE, `${label}.stderr.log`), stderr);
  return {
    command: `${cmd} ${args.join(' ')}`,
    exitStatus: r.status,
    durationMs: Date.now() - started,
    stdoutTail: stdout.split('\n').slice(-45).join('\n'),
    stderrTail: stderr.split('\n').slice(-45).join('\n'),
  };
}

function dirStats(dir) {
  if (!fs.existsSync(dir)) return { files: 0, bytes: 0 };
  let files = 0;
  let bytes = 0;
  const stack = [dir];
  while (stack.length) {
    const d = stack.pop();
    for (const name of fs.readdirSync(d)) {
      const full = path.join(d, name);
      const st = fs.lstatSync(full);
      if (st.isDirectory()) stack.push(full);
      else {
        files += 1;
        bytes += st.size;
      }
    }
  }
  return { files, bytes };
}

